import { useEffect, useRef, useState } from 'react';
import { Alert, Animated, KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View, useWindowDimensions } from 'react-native';
import { Image } from 'expo-image';
import { router, useLocalSearchParams } from 'expo-router';
import { ArrowLeft, Brain, CalendarDays, Camera, Check, ChevronRight, Copy, Heart, MapPin, MessageCircle, MoreHorizontal, Send, Sparkles, Undo2, Wand2 } from 'lucide-react-native';
import * as Clipboard from 'expo-clipboard';
import * as Haptics from 'expo-haptics';
import { CharacterAvatar, ErrorState, FrostedSurface, LoadingSkeleton, MediaTile, MoodBadge, RelationshipBadge } from '../src/components';
import { characterAssets, cityLifeAsset, locationHeroAsset, worldHeroAsset } from '../src/assets';
import { colors, radius, spacing } from '../src/theme';
import { useTogether } from '../src/store/useTogether';
import { ApiError, confirmConversationAction, createSharedPlan, dismissConversationAction, manageConversation, manageInteraction, manageMedia, mutateMemory, reportMessage, resolveRelationshipMilestone, sendDialogue, sendSceneReaction, simulate } from '../src/lib/api';
import { supabase } from '../src/lib/supabase';
import type { CharacterInstance, ConversationAction, ConversationEvent, GeneratedMedia, InteractionCandidate, Message, RelationshipMilestone, SceneAction, SceneSession, SharedPlan, Snapshot } from '../src/types';
import { activeCompanion } from '../src/lib/companionLife';
import { activeConversationFor, mergeOlderMessages } from '../src/lib/conversation';
import { confirmAction, promptText } from '../src/lib/dialogs';
import { type PlanOption } from '../src/lib/plans';
import { PlanSelection } from '../src/components/PlanSelection';
import { buildClientConversationContext, type ClientConversationContext } from '../src/lib/conversationContext';
import { createClientRequestId } from '../src/lib/requestId';
import { worldForLocation } from '../src/lib/place';

type Feedback = { kind: 'memory'|'moment'|'plan'; title: string; body: string; id?: string };
const PAGE_SIZE = 50;

export default function Chat() {
  const params = useLocalSearchParams<{ character?: string; plan?: string; draft?: string; location?: string; world?:string; activity?:string; planId?:string; repeatPlanId?:string }>();
  const { width } = useWindowDimensions();
  const showLeft = width >= 1080;
  const showRight = width >= 920;
  const { snapshot, refresh, setSnapshot, updateCompanion, applyServerDelta } = useTogether();
  const focusedPlan = params.planId && snapshot ? snapshot.sharedPlans?.find((item) => item.id === params.planId) : undefined;
  const requestedCharacter = params.character && snapshot ? snapshot.characters.find((item) => item.together_character_templates.slug === params.character||item.together_character_templates.public_handle===params.character||item.character_template_id===params.character) : undefined;
  const character = snapshot ? (focusedPlan ? snapshot.characters.find((item) => item.id === focusedPlan.character_instance_id) ?? requestedCharacter : requestedCharacter ?? activeCompanion(snapshot)) : undefined;
  const slug = character?.together_character_templates.slug ?? '';
  const conversation = snapshot&&character ? activeConversationFor(snapshot.conversations,character.id) : undefined;
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [stream, setStream] = useState('');
  const [error, setError] = useState('');
  const [feedback, setFeedback] = useState<Feedback|null>(null);
  const [showPlans, setShowPlans] = useState(params.plan === '1');
  const [planning, setPlanning] = useState(false);
  const [pendingActionId,setPendingActionId]=useState<string|null>(null);
  const [focusPlanId,setFocusPlanId]=useState<string|null>(params.planId??null);
  const [focusDismissed,setFocusDismissed]=useState(false);
  const [showPhotoRequests, setShowPhotoRequests] = useState(false);
  const [showInteractions, setShowInteractions] = useState(false);
  const [interactionCandidates, setInteractionCandidates] = useState<InteractionCandidate[]>([]);
  const [movementCandidates, setMovementCandidates] = useState<InteractionCandidate[]>([]);
  const [interactionScene, setInteractionScene] = useState<SceneSession|null>(null);
  const [interactionLoading, setInteractionLoading] = useState(false);
  const [lastInteraction, setLastInteraction] = useState<string|null>(null);
  const [showConversationMenu, setShowConversationMenu] = useState(false);
  const [resolvingMilestone, setResolvingMilestone] = useState(false);
  const [loadingOlder, setLoadingOlder] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const scroll = useRef<ScrollView>(null);
  const contentHeight = useRef(0);
  const previousHeight = useRef(0);
  const prepending = useRef(false);
  useEffect(()=>{if(params.plan==='1')setShowPlans(true);if(params.draft)setInput(params.draft);if(params.planId)setFocusPlanId(params.planId);},[params.plan,params.draft,params.planId]);
  useEffect(()=>{const focus=conversation?.metadata?.focus as Record<string,unknown>|undefined;if(!focusDismissed&&!focusPlanId&&focus?.type==='plan'&&typeof focus.planId==='string')setFocusPlanId(focus.planId);},[conversation?.id,conversation?.metadata,focusPlanId,focusDismissed]);
  const activeSceneMetadata=(conversation?.metadata?.activeScene??conversation?.metadata?.scene??null) as Record<string,unknown>|null;
  const hasActiveCommitment=Boolean(snapshot&&character&&((snapshot.sharedPlans??[]).some((plan)=>plan.character_instance_id===character.id&&isLivePlan(plan)&&Boolean(plan.attendance?.user&&!plan.attendance.user.left_at))||(snapshot.dates??[]).some((date)=>date.character_instance_id===character.id&&date.status==='active')));
  const metadataCoPresent=activeSceneMetadata?.interactionMode==='co_present'&&activeSceneMetadata?.entryReason!=='shared_plan';
  const isCoPresent=Boolean(metadataCoPresent||hasActiveCommitment);
  useEffect(()=>{
    if(!character?.id||!conversation?.id||!isCoPresent){setInteractionCandidates([]);setMovementCandidates([]);setInteractionScene(null);return;}
    let cancelled=false;setInteractionLoading(true);
    void manageInteraction<{scene:SceneSession;interactions:InteractionCandidate[];destinations:InteractionCandidate[]}>({action:'resolve',characterInstanceId:character.id,conversationId:conversation.id}).then((result)=>{if(cancelled)return;setInteractionScene(result.scene?.id?result.scene:null);setInteractionCandidates(result.interactions??[]);setMovementCandidates(result.destinations??[]);}).catch((caught)=>{if(!cancelled&&caught instanceof ApiError&&caught.code!=='SCENE_REQUIRED')setError(caught.message);}).finally(()=>{if(!cancelled)setInteractionLoading(false);});
    return()=>{cancelled=true;};
  },[character?.id,conversation?.id,isCoPresent,activeSceneMetadata?.sceneSessionId,activeSceneMetadata?.locationId]);

  const load = async () => {
    if (!conversation) return;
    if (__DEV__ && process.env.EXPO_PUBLIC_TOGETHER_DEMO_MODE === 'true') { setMessages([]); setLoading(false); return; }
    setLoading(true);
    const { data, error: loadError } = await supabase.from('together_messages').select('*').eq('conversation_id', conversation.id).order('created_at', { ascending: false }).limit(PAGE_SIZE);
    if (loadError) setError('Conversation history could not be loaded.'); else { const page=((data??[]) as Message[]).reverse();setMessages(page);setHasMore(page.length===PAGE_SIZE);void manageConversation({action:'read',conversationId:conversation.id}).then(refresh).catch(()=>undefined); }
    setLoading(false);
  };
  const loadOlder = async () => { const oldest=messages[0];if(!conversation||!oldest||loadingOlder||!hasMore)return;setLoadingOlder(true);previousHeight.current=contentHeight.current;prepending.current=true;const{data,error:olderError}=await supabase.from('together_messages').select('*').eq('conversation_id',conversation.id).lt('created_at',oldest.created_at).order('created_at',{ascending:false}).limit(PAGE_SIZE);if(olderError){setError('Earlier messages could not be loaded.');prepending.current=false;}else{const page=(data??[]) as Message[];setHasMore(page.length===PAGE_SIZE);setMessages((current)=>mergeOlderMessages(page,current));}setLoadingOlder(false);};
  useEffect(() => { void load(); }, [conversation?.id]);
  const simulationStale=Boolean(character&&(Date.now()-new Date(character.last_simulated_at).getTime()>2*60000||!(snapshot?.scheduleEvents??[]).some((item)=>item.character_instance_id===character.id&&new Date(item.ends_at)>new Date())));
  useEffect(()=>{if(!character?.id||!simulationStale)return;let cancelled=false;void simulate(character.id).then(()=>cancelled?undefined:refresh()).catch(()=>undefined);return()=>{cancelled=true;};},[character?.id,refresh,simulationStale]);
  useEffect(()=>{if(!character)return;const channel=supabase.channel(`kivelle-media-${character.id}`).on('postgres_changes',{event:'*',schema:'public',table:'together_generated_media',filter:`character_instance_id=eq.${character.id}`},()=>void refresh()).subscribe();return()=>{void supabase.removeChannel(channel);};},[character?.id,refresh]);
  useEffect(()=>{if(!character)return;const channel=supabase.channel(`kivelle-presence-${character.id}`).on('postgres_changes',{event:'*',schema:'public',table:'together_character_schedule_events',filter:`character_instance_id=eq.${character.id}`},()=>void refresh()).on('postgres_changes',{event:'UPDATE',schema:'public',table:'together_character_instances',filter:`id=eq.${character.id}`},()=>void refresh()).subscribe();return()=>{void supabase.removeChannel(channel);};},[character?.id,refresh]);
  useEffect(() => { if(prepending.current)return;const timer = setTimeout(() => scroll.current?.scrollToEnd({ animated: true }), 40); return () => clearTimeout(timer); }, [messages, stream, sending, feedback]);

  if (!snapshot || loading) return <LoadingSkeleton label="Opening your conversation…" />;
  if (!character || !conversation) return <ErrorState message="This conversation is not available yet." />;
  const chatContext=buildClientConversationContext(snapshot,character);
  const location = chatContext.scene.location;
  const milestone = snapshot.relationshipMilestones?.find((item) => item.character_instance_id === character.id);
  const prompts = chatContext.prompts;
  const pendingActions=(snapshot.conversationActions??[]).filter((item)=>item.character_instance_id===character.id&&item.conversation_id===conversation.id);

  const send = async (retryText?: string) => {
    const text = (retryText ?? input).trim(); if (!text || sending) return;
    const before = useTogether.getState().snapshot;
    setInput(''); setError(''); setSending(true); setStream(''); setFeedback(null);
    const optimistic: Message = { id: `local-${Date.now()}`, conversation_id: conversation.id, role: 'user', content: text, delivery_status: 'pending', created_at: new Date().toISOString() };
    setMessages((current) => [...current, optimistic]);
    try {
      // A clear free-text action is matched only against the server's current
      // scene candidates, then executed before the dialogue context is built.
      // This gives the normal companion response the real scene change to
      // react to, while questions and vague ideas remain ordinary chat.
      if(isCoPresent){
        try{
          const sceneResult=await manageInteraction<{scene:SceneSession;interactions:InteractionCandidate[];destinations:InteractionCandidate[];intentMatch?:InteractionCandidate}>({action:'resolve',characterInstanceId:character.id,conversationId:conversation.id,intentText:text});
          setInteractionScene(sceneResult.scene?.id?sceneResult.scene:null);
          setInteractionCandidates(sceneResult.interactions??[]);
          setMovementCandidates(sceneResult.destinations??[]);
          if(sceneResult.intentMatch)await executeInteraction(sceneResult.intentMatch,'defer_to_current_message');
        }catch{/* The sent message is still valid if the scene changed. */}
      }
      const result = await sendDialogue({ conversationId: conversation.id, characterInstanceId: character.id, message: text, clientRequestId: createClientRequestId(),focusPlanId:focusPlanId??undefined }, (token) => setStream((current) => current + token));
      setStream(''); setMessages((current) => [...current.filter((item) => item.id !== optimistic.id), { ...optimistic, delivery_status: 'complete' }, result.message]);
      if(result.delta)applyServerDelta(result.delta);
      showNewStoryFeedback(before, useTogether.getState().snapshot, character.id, character.together_character_templates.name, setFeedback);
    } catch (caught) {
      setStream(''); setError(caught instanceof Error ? caught.message : 'The reply was interrupted.');
      if(caught instanceof ApiError&&caught.code==='CONVERSATION_ARCHIVED')await refresh();
      setMessages((current) => current.map((item) => item.id === optimistic.id ? { ...item, delivery_status: 'failed' } : item));
    } finally { setSending(false); }
  };

  const plan = async (option:PlanOption,scheduledFor:string) => {
    setPlanning(true); setError('');
    try {
      if(pendingActionId){await confirmConversationAction(pendingActionId,{activityKey:option.activityKey,locationId:option.locationId,startsAt:scheduledFor});await refresh();setPendingActionId(null);setShowPlans(false);}
      else{await createSharedPlan({activityKey:option.activityKey,locationId:option.locationId,characterInstanceId:character.id,startsAt:scheduledFor,requestId:createClientRequestId(),source:params.location?'location':'manual_planner',sourceConversationId:conversation.id});await refresh();setShowPlans(false);}
      if(Platform.OS!=='web')void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
    catch (caught) { setError(caught instanceof Error ? caught.message : 'The plan could not be saved.'); }
    finally { setPlanning(false); }
  };
  const undoMemory = async () => { if (!feedback?.id) return; await mutateMemory({ action:'forget', memoryId:feedback.id }); await refresh(); setFeedback(null); };
  const resolveInteractions = async () => {
    if(!isCoPresent){setError(`Join ${character.together_character_templates.name} at their current location to do something together.`);return;}
    setInteractionLoading(true);setError('');
    try{const result=await manageInteraction<{scene:SceneSession;interactions:InteractionCandidate[];destinations:InteractionCandidate[]}>({action:'resolve',characterInstanceId:character.id,conversationId:conversation.id});setInteractionScene(result.scene?.id?result.scene:null);setInteractionCandidates(result.interactions??[]);setMovementCandidates(result.destinations??[]);setShowInteractions(true);}catch(caught){setError(caught instanceof Error?caught.message:'The shared scene is no longer available.');}finally{setInteractionLoading(false);}
  };
  const applySceneDelta = (scene:SceneSession|null|undefined) => {
    if(!scene?.id)return;
    updateCompanion({...character,current_location_id:scene.location_id,current_activity:sceneActivityLabel(scene),current_interruptibility:'open',current_presence_source:'scene'});
  };
  const executeInteraction = async (candidate:InteractionCandidate,reactionMode:'generate'|'defer_to_current_message'='generate') => {
    if(interactionLoading)return;setInteractionLoading(true);setError('');
    try{const result=await manageInteraction<{scene:SceneSession;interactions:InteractionCandidate[];destinations:InteractionCandidate[];action?:SceneAction}>({action:'execute',characterInstanceId:character.id,conversationId:conversation.id,sceneId:interactionScene?.id,interactionKey:candidate.interactionKey,requestId:createClientRequestId()});setInteractionScene(result.scene?.id?result.scene:null);applySceneDelta(result.scene);setInteractionCandidates(result.interactions??[]);setMovementCandidates(result.destinations??[]);setLastInteraction(candidate.label);setShowInteractions(false);if(Platform.OS!=='web')void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);if(reactionMode==='generate'&&result.action?.id){setSending(true);setStream('');try{const reaction=await sendSceneReaction({conversationId:conversation.id,characterInstanceId:character.id,sceneActionId:result.action.id,clientRequestId:createClientRequestId()},(token)=>setStream((current)=>current+token));setStream('');setMessages((current)=>[...current,reaction.message]);}catch(caught){setStream('');setError(caught instanceof Error?caught.message:'The action happened, but the reaction was interrupted.');}finally{setSending(false);}}}catch(caught){setError(caught instanceof Error?caught.message:'That option is no longer available.');}finally{setInteractionLoading(false);}
  };
  const moveScene = async (candidate:InteractionCandidate) => {
    const destinationId=typeof candidate.effects.destinationLocationId==='string'?candidate.effects.destinationLocationId:null;if(!destinationId)return;
    if(interactionLoading)return;setInteractionLoading(true);setError('');
    try{const result=await manageInteraction<{scene:SceneSession;interactions:InteractionCandidate[];destinations:InteractionCandidate[]}>({action:'move',characterInstanceId:character.id,conversationId:conversation.id,sceneId:interactionScene?.id,destinationLocationId:destinationId,requestId:createClientRequestId()});setInteractionScene(result.scene?.id?result.scene:null);applySceneDelta(result.scene);setInteractionCandidates(result.interactions??[]);setMovementCandidates(result.destinations??[]);setLastInteraction(candidate.label);setShowInteractions(false);if(Platform.OS!=='web')void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);}catch(caught){setError(caught instanceof Error?caught.message:'That place is no longer available right now.');}finally{setInteractionLoading(false);}
  };
  const resolveMilestone = async (action:RelationshipMilestone['choices'][number]['id']) => { if(!milestone||resolvingMilestone)return;setResolvingMilestone(true);setError('');try{const result=await resolveRelationshipMilestone(milestone.id,action);setSnapshot(result.snapshot);if(milestone.kind==='first_date_invitation'&&action==='accept')setFeedback({kind:'moment',title:`${milestone.title} unlocked`,body:'Your shared experience is ready in Dates.'});}catch(caught){setError(caught instanceof Error?caught.message:'That choice could not be saved.');}finally{setResolvingMilestone(false);} };
  const startNewConversation=()=>confirmAction({title:'Start a fresh chat?',message:`This creates a clean transcript with ${character.together_character_templates.name}. Your memories, plans, relationship, and relationship day will continue; use "Start over" in Conversation settings to erase them.`,confirmLabel:'Start fresh chat',onConfirm:async()=>{try{await manageConversation({action:'new',characterInstanceId:character.id});setMessages([]);setShowConversationMenu(false);await refresh();}catch(caught){setError(caught instanceof Error?caught.message:'A new conversation could not be started.');}}});
  const renameConversation=()=>promptText({title:'Rename conversation',message:'Choose a title that will help you find this chat later.',initialValue:conversation.title??'',onSubmit:async(title)=>{try{await manageConversation({action:'rename',conversationId:conversation.id,title});setShowConversationMenu(false);await refresh();}catch(caught){setError(caught instanceof Error?caught.message:'The conversation could not be renamed.');}}});
  const deleteConversation=()=>confirmAction({title:'Delete this conversation?',message:`These messages will be permanently removed.\n\n${character.together_character_templates.name} will still remember saved memories and your relationship will remain unchanged. Moments and photos in your shared history will remain.`,confirmLabel:'Delete conversation',destructive:true,onConfirm:async()=>{try{await manageConversation({action:'delete',conversationId:conversation.id});setMessages([]);setShowConversationMenu(false);await refresh();}catch(caught){setError(caught instanceof Error?caught.message:'The conversation could not be deleted.');}}});

  return <KeyboardAvoidingView style={styles.screen} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
    <View style={styles.shell}>
      {showLeft ? <LeftRail snapshot={snapshot} active={slug} /> : null}
      <View style={styles.conversation}>
        <ChatHeader character={character} location={location} relationshipStage={character.relationship_stage} onMenu={()=>setShowConversationMenu((value)=>!value)} />
        {!showRight&&chatContext.nextCommitment?<Pressable onPress={()=>chatContext.nextCommitment?.kind==='plan'&&router.push(`/plan/${chatContext.nextCommitment.id}` as never)} style={styles.mobileCommitment}><CalendarDays size={14} color={colors.rose}/><Text style={styles.mobileCommitmentText} numberOfLines={1}>{new Date(chatContext.nextCommitment.startsAt).toLocaleDateString([],{weekday:'short'})} · {chatContext.nextCommitment.title}</Text><ChevronRight size={14} color={colors.muted}/></Pressable>:null}
        {showConversationMenu ? <ConversationMenu name={character.together_character_templates.name} onClose={()=>setShowConversationMenu(false)} actions={{profile:()=>router.push(`/character/${slug}` as never),plan:()=>{setShowPlans(true);setShowConversationMenu(false);},memories:()=>router.push(`/memories?character=${slug}` as never),history:()=>router.push(`/conversations/${character.id}` as never),settings:()=>router.push('/conversation-controls'),start:startNewConversation,rename:renameConversation,remove:deleteConversation}} /> : null}
        {showPhotoRequests ? <PhotoRequestTray name={character.together_character_templates.name} onRequest={(request)=>{setShowPhotoRequests(false);void send(request);}} onClose={()=>setShowPhotoRequests(false)}/> : null}
        {showPlans ? <ScrollView style={styles.planScroll} contentContainerStyle={styles.planScrollContent} keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator={false}>
          <PlanSelection snapshot={snapshot} character={character} scopedLocationId={resolveScopedLocation(snapshot,params.location,params.world,pendingActions.find((item)=>item.id===pendingActionId),params.repeatPlanId)} initialActivityKey={params.activity} repeatPlanId={params.repeatPlanId} proposal={pendingActions.find((item)=>item.id===pendingActionId)} interests={[...(snapshot.profile?.interests??[]),...snapshot.memories.filter((item)=>item.character_instance_id===character.id&&item.memory_type==='preference').map((item)=>item.canonical_text)]} busy={planning} onPlan={(option,scheduledFor) => void plan(option,scheduledFor)} onClose={() => {setShowPlans(false);setPendingActionId(null);}} />
        </ScrollView> : <ScrollView ref={scroll} style={styles.messageScroll} contentContainerStyle={styles.messages} keyboardShouldPersistTaps="handled" scrollEventThrottle={80} onScroll={(event)=>{if(event.nativeEvent.contentOffset.y<80)void loadOlder();}} onContentSizeChange={(_,height)=>{contentHeight.current=height;if(prepending.current){scroll.current?.scrollTo({y:Math.max(0,height-previousHeight.current),animated:false});prepending.current=false;}}}>
          {loadingOlder?<Text style={styles.olderLoading}>Loading earlier messages…</Text>:!hasMore&&messages.length?<Text style={styles.historyStart}>Beginning of this conversation</Text>:null}
          <SceneCard character={character} context={chatContext} snapshot={snapshot} />
          {messages.length === 0 ? <EmptyConversation character={character} prompts={prompts} onPrompt={setInput} /> : null}
          {mergeChatTimeline(messages,pendingActions,(snapshot.conversationEvents??[]).filter((event)=>event.conversation_id===conversation.id),conversation.last_read_at).map((item,index,timeline)=>item.kind==='separator'?<Text key={item.key} style={[styles.day,item.label==='NEW'&&{color:colors.rose}]}>{item.label}</Text>:item.kind==='message'?<MessageBubble key={item.value.id} message={item.value} character={character} media={(snapshot.generatedMedia??[]).filter((media)=>media.message_id===item.value.id)} grouped={index>0&&timeline[index-1]?.kind==='message'&&(timeline[index-1] as {kind:'message';value:Message}).value.role===item.value.role} onMediaRetry={async(mediaId)=>{await manageMedia({action:'retry',mediaId});await refresh();}}/>:item.kind==='action'?<ConversationActionCard key={item.value.id} action={item.value} busy={planning} onConfirm={async(planId)=>{const proposed=typeof item.value.payload.proposedStartsAt==='string'?item.value.payload.proposedStartsAt:null,validProposed=Boolean(proposed&&new Date(proposed).getTime()>=Date.now()+10*60000),direct=['plan_cancel','cancel_plan'].includes(item.value.candidate_type)||validProposed||Boolean(planId);if(!direct){setPendingActionId(item.value.id);setShowPlans(true);return;}setPlanning(true);try{await confirmConversationAction(item.value.id,{planId,startsAt:validProposed?proposed??undefined:undefined});await refresh();}catch(caught){setError(caught instanceof Error?caught.message:'That action could not be completed.');}finally{setPlanning(false);}}} onChange={()=>{setPendingActionId(item.value.id);setShowPlans(true);}} onDismiss={async()=>{await dismissConversationAction(item.value.id);await refresh();}}/>:<PlanTimelineCard key={item.value.id} event={item.value} plan={(snapshot.sharedPlans??[]).find((plan)=>plan.id===item.value.entity_id)}/>)}
          {stream ? <StreamingBubble character={character} content={stream} /> : null}
          {sending && !stream ? <TypingState name={character.together_character_templates.name} /> : null}
          {milestone ? <RelationshipMomentCard milestone={milestone} busy={resolvingMilestone} onChoose={(action)=>void resolveMilestone(action)} /> : null}
          {!milestone && !sending && messages.length ? <SuggestedReplies prompts={prompts} interactions={isCoPresent?interactionCandidates.slice(0,2):[]} onSelect={setInput} onInteraction={(candidate)=>void executeInteraction(candidate)} /> : null}
          {lastInteraction?<SceneActionFeedback label={lastInteraction} onDismiss={()=>setLastInteraction(null)} />:null}
          {feedback ? <StoryFeedback feedback={feedback} onView={() => router.push(feedback.kind === 'memory' ? '/memories' : feedback.kind==='plan'? '/(tabs)/dates':'/moments')} onUndo={feedback.kind === 'memory' ? () => void undoMemory() : undefined} onDismiss={() => setFeedback(null)} /> : null}
          {error ? <Pressable onPress={() => { const failed = [...messages].reverse().find((item) => item.delivery_status === 'failed'); if (failed) void send(failed.content); }} style={styles.retry}><Text style={styles.retryText}>{error}{messages.some((item) => item.delivery_status === 'failed') ? ' Tap to retry.' : ''}</Text></Pressable> : null}
        </ScrollView>}
        {showInteractions?<InteractionTray name={character.together_character_templates.name} location={location} loading={interactionLoading} interactions={interactionCandidates} destinations={movementCandidates} onInteraction={(candidate)=>void executeInteraction(candidate)} onMove={(candidate)=>void moveScene(candidate)} onClose={()=>setShowInteractions(false)} />:isCoPresent&&interactionCandidates.length?<ContextualInteractionTray loading={interactionLoading} interactions={interactionCandidates.slice(0,3)} onOpen={()=>setShowInteractions(true)} onInteraction={(candidate)=>void executeInteraction(candidate)} />:null}
        {focusPlanId?<PlanFocusChip plan={(snapshot.sharedPlans??[]).find((item)=>item.id===focusPlanId)} onOpen={(id)=>router.push(`/plan/${id}` as never)} onClose={()=>{setFocusPlanId(null);setFocusDismissed(true);}}/>:null}
        <Composer character={character} compact={width < 480} input={input} setInput={setInput} sending={sending} onSend={() => void send()} onPlan={() => setShowPlans((value) => !value)} onPhoto={()=>setShowPhotoRequests((value)=>!value)} onInteraction={()=>void resolveInteractions()} onMove={()=>{void resolveInteractions();setShowInteractions(true);}} coPresent={isCoPresent} />
      </View>
      {showRight ? <ContextRail snapshot={snapshot} character={character} context={chatContext} onPrompt={setInput} onPlan={() => setShowPlans(true)} /> : null}
    </View>
  </KeyboardAvoidingView>;
}

function ChatHeader({character,location,relationshipStage,onMenu}:{character:CharacterInstance;location:string;relationshipStage:string;onMenu:()=>void}) { const slug=character.together_character_templates.slug;const leaveChat=()=>{if(router.canGoBack())router.back();else router.replace('/home');};return <View style={[styles.header, Platform.OS === 'web' && styles.webHeader]}><Pressable accessibilityLabel="Back to Home" onPress={leaveChat} style={styles.icon}><ArrowLeft color={colors.text}/></Pressable><Pressable accessibilityLabel={`View ${character.together_character_templates.name}'s profile`} onPress={()=>router.push(`/character/${slug}` as never)}><CharacterAvatar slug={slug} name={character.together_character_templates.name} size={42} ring/></Pressable><Pressable onPress={()=>router.push(`/character/${slug}` as never)} style={{flex:1}}><View style={styles.nameLine}><Text style={styles.name}>{character.together_character_templates.name}</Text><MoodBadge mood={character.current_mood}/></View><Text style={styles.status}>At {location} · {character.current_activity}</Text></Pressable><RelationshipBadge stage={relationshipStage}/><Pressable accessibilityLabel="Conversation menu" onPress={onMenu} style={styles.icon}><MoreHorizontal color={colors.text}/></Pressable></View>; }

function ConversationMenu({name,onClose,actions}:{name:string;onClose:()=>void;actions:Record<'profile'|'plan'|'memories'|'history'|'settings'|'start'|'rename'|'remove',()=>void>}) { const item=(label:string,action:()=>void,danger=false)=><Pressable key={label} onPress={action} style={styles.menuItem}><Text style={[styles.menuItemText,danger&&{color:colors.danger}]}>{label}</Text></Pressable>;return <FrostedSurface intensity={82} style={styles.menu}><View style={styles.menuTop}><Text style={styles.menuTitle}>{name}</Text><Pressable onPress={onClose}><Text style={styles.closeText}>Close</Text></Pressable></View><Text style={styles.menuSection}>COMPANION</Text>{item('View profile',actions.profile)}{item('Plan something',actions.plan)}{item(`What ${name} remembers`,actions.memories)}<Text style={styles.menuSection}>CONVERSATION</Text>{item('Start a fresh chat',actions.start)}{item('Conversation history & search',actions.history)}{item('Rename conversation',actions.rename)}<Text style={styles.menuSection}>MANAGE</Text>{item('Conversation settings',actions.settings)}{item('Delete this conversation',actions.remove,true)}</FrostedSurface>; }

function LeftRail({snapshot,active}:{snapshot:Snapshot;active:string}) { return <View style={styles.leftRail}><Text style={styles.brand}>Kivelle.AI</Text><Text style={styles.railKicker}>CONVERSATIONS</Text>{snapshot.characters.filter((item)=>item.introduced_at).map((item)=>{const activeConversation=snapshot.conversations.find((conversation)=>conversation.character_instance_id===item.id&&!conversation.archived_at);return <Pressable key={item.id} onPress={()=>router.replace(`/chat?character=${item.together_character_templates.slug}` as never)} style={[styles.personRow,item.together_character_templates.slug===active&&styles.personActive]}><CharacterAvatar slug={item.together_character_templates.slug}/><View style={{flex:1}}><Text style={styles.personName}>{item.together_character_templates.name}</Text><Text style={styles.personMeta} numberOfLines={1}>{item.current_activity}</Text></View>{activeConversation?.unread?<View style={styles.unreadDot}/>:null}</Pressable>;})}<Text style={styles.railKicker}>CITY LIFE</Text>{snapshot.lifeEvents.slice(0,3).map((event)=><View key={event.id} style={styles.railEvent}><Sparkles size={14} color={colors.warm}/><View style={{flex:1}}><Text style={styles.railEventTitle}>{event.title}</Text><Text style={styles.personMeta} numberOfLines={2}>{event.narrative_summary}</Text></View></View>)}</View>; }

function ContextRail({snapshot,character,context,onPrompt,onPlan}:{snapshot:Snapshot;character:CharacterInstance;context:ClientConversationContext;onPrompt:(value:string)=>void;onPlan:()=>void}) { const memories=snapshot.memories.filter((item)=>item.character_instance_id===character.id).slice(0,3);return <ScrollView style={styles.rightRail} contentContainerStyle={styles.rightContent}><Image source={characterAssets[character.together_character_templates.slug]} style={styles.contextPortrait} contentFit="cover" contentPosition="top"/><Text style={styles.contextName}>{character.together_character_templates.name}</Text><Text style={styles.contextBio}>{character.together_character_templates.occupation} · {relationshipLabel(character.relationship_stage)}</Text>{context.nextCommitment?<ContextSection title="NEXT TOGETHER"><Pressable onPress={()=>context.nextCommitment?.kind==='plan'&&router.push(`/plan/${context.nextCommitment.id}` as never)}><ContextLine icon={<CalendarDays size={15} color={colors.rose}/>} title={context.nextCommitment.title} body={`${new Date(context.nextCommitment.startsAt).toLocaleString([],{weekday:'short',hour:'numeric',minute:'2-digit'})}${context.nextCommitment.location?` · ${context.nextCommitment.location}`:''}`}/></Pressable></ContextSection>:null}<ContextSection title={context.interactionMode==='co_present'?'TOGETHER NOW':`${character.together_character_templates.name.toUpperCase()} RIGHT NOW`}><ContextLine icon={<MapPin size={15} color={colors.warm}/>} title={context.scene.location} body={context.scene.activity}/></ContextSection>{context.story?<ContextSection title="CURRENT STORY"><ContextLine icon={<Sparkles size={15} color={colors.violet}/>} title={context.story.title} body={context.story.chapter}/></ContextSection>:null}{context.thread?<Pressable onPress={()=>onPrompt(context.thread!.prompt)} style={styles.threadCard}><CalendarDays size={16} color={colors.rose}/><View style={{flex:1}}><Text style={styles.threadTitle}>FOLLOW UP</Text><Text style={styles.contextCopy}>{context.thread.label}</Text></View><ChevronRight size={16} color={colors.muted}/></Pressable>:null}<ContextSection title={`WHAT ${character.together_character_templates.name.toUpperCase()} REMEMBERS`}>{memories.length?memories.map((memory)=><Pressable key={memory.id} onPress={()=>router.push(`/memories?character=${character.together_character_templates.slug}` as never)} style={styles.memoryLine}><Brain size={14} color={memory.pinned?colors.rose:colors.violet}/><Text style={styles.contextCopy} numberOfLines={2}>{presentMemoryText(memory.canonical_text,memory.memory_type)}</Text></Pressable>):<Text style={styles.contextMuted}>Meaningful details will collect here.</Text>}</ContextSection><Pressable onPress={onPlan} style={styles.planButton}><CalendarDays size={17} color="#fff"/><Text style={styles.planButtonText}>Plan something</Text></Pressable><Pressable onPress={()=>router.push(`/memories?character=${character.together_character_templates.slug}` as never)} style={styles.secondaryButton}><Brain size={17} color={colors.rose}/><Text style={styles.secondaryButtonText}>Memory Center</Text></Pressable></ScrollView>; }

function presentMemoryText(text:string,type:string){const cleaned=text.replace(/^User\s+(likes|dislikes|hates|loves)\s+/i,'You $1 ').replace(/^User told (?:Maya|the character)\s+/i,'You told them ');if(cleaned!==text)return cleaned;return type==='preference'&&!/^You\b/i.test(text)?`You mentioned ${text.charAt(0).toLowerCase()}${text.slice(1)}`:text;}

function SceneCard({character,context,snapshot}:{character:CharacterInstance;context:ClientConversationContext;snapshot:Snapshot}) { const location=snapshot.locations.find((item)=>item.id&&(context.scene.locationId??character.current_location_id)===item.id);const world=location?worldForLocation(snapshot,location.id):undefined;const fallback=location?locationHeroAsset(world?.slug,location.slug):world?worldHeroAsset(world.slug):cityLifeAsset;return <View style={[styles.scene,context.interactionMode==='co_present'&&{borderColor:colors.rose}]}><Image source={context.scene.mediaUrl?{uri:context.scene.mediaUrl}:fallback} style={StyleSheet.absoluteFill} contentFit="cover"/><View style={styles.sceneShade}><View style={styles.sceneTop}><Text style={styles.sceneKicker}>{context.interactionMode==='co_present'?'TOGETHER NOW':`${character.together_character_templates.name.toUpperCase()} RIGHT NOW`}</Text><Text style={styles.sceneTime}>{context.scene.localTime}</Text></View><Text style={styles.sceneTitle}>{context.scene.location}</Text><Text style={styles.sceneCopy}>{context.scene.summary}</Text><View style={styles.scenePeople}><CharacterAvatar slug={character.together_character_templates.slug} size={28}/><Text style={styles.scenePeopleText}>{character.together_character_templates.name} · {character.current_mood}</Text></View></View></View>; }
function sceneActivityLabel(scene:SceneSession){const explicit=typeof scene.state?.activityLabel==='string'?scene.state.activityLabel.trim():'';if(explicit)return explicit;const key=String(scene.state?.currentActivityKey??scene.activity_key??'together').replace(/[_-]+/g,' ').trim();return key&&key!=='together'?key.replace(/^./,(character)=>character.toUpperCase()):'Spending time together';}

function ConversationActionCard({action,busy,onConfirm,onChange,onDismiss}:{action:ConversationAction;busy:boolean;onConfirm:(planId?:string)=>void;onChange:()=>void;onDismiss:()=>void}){
  const cancel=['plan_cancel','cancel_plan'].includes(action.candidate_type),reschedule=['plan_reschedule','reschedule_plan'].includes(action.candidate_type),options=Array.isArray(action.payload.options)?action.payload.options as Array<Record<string,unknown>>:[];
  const title=String(action.payload.proposedTitle??action.payload.title??(cancel?'Cancel this plan?':reschedule?'Change this plan?':'Make this a real plan?')),rawStarts=action.payload.proposedStartsAt??action.payload.startsAt,starts=rawStarts&&new Date(String(rawStarts)).getTime()>=Date.now()+10*60000?rawStarts:null,locationLabel=action.payload.proposedLocation?String(action.payload.proposedLocation):action.payload.location?String(action.payload.location):'';
  const detail=starts?`${new Date(String(starts)).toLocaleString([],{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}${locationLabel?` · ${locationLabel}`:''}`:'Choose the time before anything is saved.';
  return <View style={styles.actionCard}><View style={styles.actionIcon}><CalendarDays size={18} color={colors.rose}/></View><View style={{flex:1}}><Text style={styles.actionKicker}>{cancel?'CANCEL PLAN':reschedule?'CHANGE PLAN':'MAKE A PLAN'}</Text><Text style={styles.actionTitle}>{options.length?'Which plan?':title}</Text>{options.length?options.map((option)=><Pressable key={String(option.planId)} disabled={busy} onPress={()=>onConfirm(String(option.planId))} style={styles.planTarget}><Text style={styles.planOptionTitle}>{String(option.title)}</Text><Text style={styles.contextMuted}>{new Date(String(option.startsAt)).toLocaleString([],{weekday:'short',hour:'numeric',minute:'2-digit'})} · {String(option.location??'City Life')}</Text></Pressable>):<Text style={styles.contextMuted}>{detail}</Text>}{!options.length?<View style={styles.actionButtons}><Pressable disabled={busy} onPress={()=>onConfirm()} style={styles.actionPrimary}><Text style={styles.actionPrimaryText}>{busy?'Working…':cancel?'Cancel plan':starts?(reschedule?'Save change':'Save plan'):'Choose time'}</Text></Pressable>{!cancel?<Pressable disabled={busy} onPress={onChange} style={styles.actionSecondary}><Text style={styles.actionSecondaryText}>Change</Text></Pressable>:null}<Pressable disabled={busy} onPress={onDismiss} style={styles.actionSecondary}><Text style={styles.actionSecondaryText}>Not now</Text></Pressable></View>:null}</View></View>;
}

function MessageBubble({message,character,media,grouped,onMediaRetry}:{message:Message;character:CharacterInstance;media:GeneratedMedia[];grouped:boolean;onMediaRetry:(id:string)=>Promise<void>}) { const[hovered,setHovered]=useState(false);const opacity=useRef(new Animated.Value(0)).current;const translate=useRef(new Animated.Value(8)).current;useEffect(()=>{Animated.parallel([Animated.timing(opacity,{toValue:1,duration:220,useNativeDriver:true}),Animated.timing(translate,{toValue:0,duration:220,useNativeDriver:true})]).start();},[]);const assistant=message.role==='assistant';const actions=()=>Alert.alert('Message actions',undefined,[{text:'Copy',onPress:()=>void Clipboard.setStringAsync(message.content)},...(assistant?[{text:'Report response',onPress:()=>void reportMessage(message.id,'other')}]:[]),{text:'Cancel',style:'cancel'}] as never);return <Animated.View style={[styles.messageRow,assistant?styles.assistantRow:styles.userRow,{opacity,transform:[{translateY:translate}]}]}>{assistant&&!grouped?<CharacterAvatar slug={character.together_character_templates.slug} size={28}/>:assistant?<View style={{width:28}}/>:null}<Pressable onHoverIn={()=>setHovered(true)} onHoverOut={()=>setHovered(false)} onLongPress={actions} style={[styles.bubble,assistant?styles.assistantBubble:styles.userBubble,message.delivery_status==='failed'&&styles.failed]}><Text style={styles.messageText}>{message.content}</Text>{media.map((item)=><MediaTile key={item.id} media={item} style={styles.messageMedia} onRetry={()=>void onMediaRetry(item.id)}/>) }<View style={styles.messageMeta}><Text style={[styles.timestamp,{opacity:hovered||Platform.OS!=='web'?1:.35}]}>{new Date(message.created_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</Text>{hovered&&Platform.OS==='web'?<Pressable onPress={()=>void Clipboard.setStringAsync(message.content)}><Copy size={12} color={colors.muted}/></Pressable>:null}</View></Pressable></Animated.View>; }

